void compensatePayment(Long orderId) { paymentRepository.deleteByOrderId(orderId); }

// RIGHT: a real refund, safe to run twice
void compensatePayment(Long orderId) {
    Payment p = payments.findByOrderId(orderId);
    if (p.isRefunded()) return;
    gateway.refund(p.chargeId(), "refund-" + orderId);   // idempotency key
    p.markRefunded();
}

@Component
class StockListener {
    @Transactional
    @KafkaListener(topics = "orders.created", groupId = "stock")
    void onOrderCreated(OrderCreated event) {
        // INSERT with UNIQUE(event_id) in the same transaction as the reservation:
        // a concurrent redelivery fails on the constraint instead of reserving twice
        if (!processed.register(event.eventId())) return;
        stock.reserve(event.items());
    }
}

